def _rows(text):
    out = []
    for tok in text.split():
        t, o, h, l, c, v = tok.split(",")
        out.append((int(t), float(o), float(h), float(l), float(c), int(v)))
    return out


FIXTURES = [(_rows(b), e) for b, e in SERIES]
#: The first series, for rails that want one chart.
ROWS, EXPECTED = FIXTURES[0]


def test_the_fixtures_are_what_the_rail_says_they_are():
    fired = set()
    for rows, exp in FIXTURES:
        assert len(rows) == 860
        assert [r[0] for r in rows] == sorted({r[0] for r in rows})     # ascending, no duplicate session
        assert len(exp) < (len(rows) - 220) / 4                         # most bars draw nothing
        fired |= {s for v in exp.values() for s in v}
    assert fired == set(SETUPS)                                         # every setup draws somewhere
    assert {s for v in EXPECTED.values() for s in v} == set(SETUPS)     # and all three on the first series


@pytest.mark.parametrize("k", range(len(SERIES)))
def test_production_reproduces_the_judged_drawing_as_of_every_bar(k):
    rows, exp = FIXTURES[k]
    mismatches = []
    for i in range(220, len(rows)):
        got = setup_draw.detect_all(rows[:i + 1])
        want = exp.get(str(i), {})
        for s in SETUPS:
            a = json.dumps(want.get(s), sort_keys=True)
            b = json.dumps(got[s], sort_keys=True)
            if a != b:
                mismatches.append((i, s, a[:160], b[:160]))
    assert not mismatches, mismatches[:5]


@pytest.mark.parametrize("setup", SETUPS)
def test_each_setup_draws_its_judged_line(setup):
    """The line itself, named: both first anchors AT the level (the overlay draws their mean), solid (5 anchors)
    for remount / u_and_r and dashed (2 anchors) for donchian."""
    hits = [(rows, int(k), v[setup]) for rows, exp in FIXTURES for k, v in exp.items() if setup in v]
    assert hits
    for rows, i, want in hits:
        got = setup_draw.detect(setup, rows[:i + 1])
        assert got == want
        a = got["det"]["geometry"]["anchors"]
        assert got["det"]["geometry"]["shape"] == "horizontal_line"
        assert a[0]["price"] == a[1]["price"] == round(got["level"], 4)
        assert len(a) == (2 if setup == "donchian_breakout" else 5)
        assert got["draw_round"] == setup_draw.DRAW_ROUNDS[setup]


def test_dict_bars_as_the_route_passes_them_draw_the_same():
    """auto_structures hands {t,o,h,l,c,v} dicts (the completed-session window); the rail's tuples and those dicts
    must give the identical drawing."""
    for rows, exp in FIXTURES:
        for k, v in exp.items():
            i = int(k)
            dicts = [{"t": r[0], "o": r[1], "h": r[2], "l": r[3], "c": r[4], "v": r[5]} for r in rows[:i + 1]]
            for s, want in v.items():
                assert setup_draw.detect(s, dicts) == want


def test_the_judged_constants_are_pinned():
    got = {c: getattr(setup_draw, c) for c in JUDGED_CONSTANTS}
    assert got == JUDGED_CONSTANTS
    assert setup_draw.DRAW_ROUNDS == {"remount": 3, "u_and_r": 2, "donchian_breakout": 1}
